function deskPart(){const t=today(),nm=nowMin(),ps=dayParts(t).filter(p=>asg(t,p)),und=ps.filter(p=>!doneLog(t,p.id)),cur=ps.find(p=>nm>=p.s&&nm<p.e),nx=und.find(p=>p.s>nm);return{cur,nx,p:cur||nx||und[0]||null}}
