let ticks='';for(let i=0;i<12;i++)ticks+=`<line x1=150 y1=26 x2=150 y2=${i%3?36:44} transform="rotate(${i*30} 150 150)" stroke="rgba(255,255,255,.55)" stroke-width=${i%3?3:5} stroke-linecap=round />`;
