const fontsReady=async()=>{try{await Promise.all(['400','500','600','700','800'].map(w=>document.fonts.load(w+' 40px Vazirmatn')))}catch(e){}};
function cvs(w,h){const c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d');if(!x)throw new Error('امکان ساخت تصویر در این دستگاه فراهم نیست.');x.direction='rtl';x.imageSmoothingEnabled=true;x.imageSmoothingQuality='high';return[c,x]}
