function paintBg(x,w,h,T){x.fillStyle=T.bg;x.fillRect(0,0,w,h);let g=x.createLinearGradient(0,0,w,h);g.addColorStop(0,hexA(T.ac,.25));g.addColorStop(.52,hexA(T.bg,0));g.addColorStop(1,hexA(T.a2,.24));x.fillStyle=g;x.fillRect(0,0,w,h);g=x.createRadialGradient(w*.1,h*.05,0,w*.1,h*.05,w*.9);g.addColorStop(0,hexA(T.ac,.24));g.addColorStop(1,hexA(T.ac,0));x.fillStyle=g;x.fillRect(0,0,w,h);x.save();x.globalAlpha=.12;x.strokeStyle=T.fg;x.lineWidth=2;for(let i=0;i<4;i++){x.beginPath();x.arc(w-20,120,100+i*38,0,Math.PI*2);x.stroke()}x.restore()}
