function timeMenu(date,pid){const p=findPart(pid);if(!p)return;if(date>today())return toast('برای روزهای آینده نمی‌شود زمان ثبت کرد.');const entries=partTimeEntries(date,pid),sum=partTimeSeconds(date,pid),past=date!==today();M={kind:'time',date,pid,t:'ثبت زمان · '+esc(p.name),b:`<div class="muted sm">${DAYS[wd(date)]} · ${fj(date,1)} ${past?'· ثبت دستی برای این تاریخ':''}</div><div class=time-choice>${!past?`<button data-a=chooseTimer><span class=tc-icon>◷</span><b>تایمر زنده</b><small>صفحه‌ی تمام‌صفحه با شمارنده‌ی زنده و پس‌زمینه‌ی اختصاصی</small></button>`:''}<button data-a=chooseManual><span class=tc-icon>⌁</span><b>ثبت دستی</b><small>مدت مطالعه را خودت وارد کن؛ مناسب امروز و تاریخ‌های گذشته</small></button></div><div class="time-record"><div class=grow><div class="muted sm">مجموع زمان این پارت در این روز</div><b>${fsec(sum)}</b></div></div>${entries.length?`<h3 style="margin:18px 0 6px">ثبت‌های قبلی</h3>${entries.map(x=>`<div class=time-record><div class=grow><b>${clockText(x.seconds)}</b><div class="muted sm">${x.method=='timer'?'تایمر زنده':'ثبت دستی'}</div></div><button data-a=editTime data-id=${x.id} aria-label="ویرایش">✎</button><button data-a=deleteTime data-id=${x.id} aria-label="حذف">×</button></div>`).join('')}`:''}`};render()}
function manualTimeForm(date,pid,id){const old=id?S.timeEntries.find(x=>x.id==id):null,p=findPart(pid);if(!p)return;const sec=old?old.seconds:0;M={kind:'time',date,pid,t:old?'ویرایش ثبت زمان':'ثبت دستی زمان',b:`<div class="muted sm">${esc(p.name)} · ${fj(date,1)}</div><div class=row style="margin-top:16px"><div class=grow><label>ساعت</label><input id=timeHours type=text data-num=1 inputmode=numeric value=${~~(sec/3600)}></div><div class=grow><label>دقیقه</label><input id=timeMinutes type=text data-num=1 inputmode=numeric value=${~~(sec%3600/60)}></div></div><div class=row style="margin-top:10px">${[15,30,45,60].map(m=>`<button type=button class=chip data-a=qadd data-m=${m}>+${fa(m)} دقیقه</button>`).join('')}</div><p class="muted sm">با دکمه‌ها زمان را سریع اضافه کن؛ مقدار نهایی به مجموع ثبت‌های همین پارت افزوده می‌شود.</p>`,s(){const h=+nd($('#timeHours').value)||0,m=+nd($('#timeMinutes').value)||0;if(h<0||m<0||m>59||h>99||h*3600+m*60<=0)return err('مدت زمان را درست وارد کن.');const seconds=h*3600+m*60;if(old){old.seconds=seconds;const l=S.logs.find(x=>x.id==old.logId);if(l)l.min=seconds/60}else{const a=asg(date,p),eid=uid(),logId=uid();S.timeEntries.push({id:eid,date,part:pid,seconds,method:'manual',createdAt:Date.now(),logId});S.logs.push({id:logId,date,c:a?.c||'',tp:a?.tp||'',min:seconds/60,src:'manual-time',part:pid,h:~~(p.s/60)})}syncPartLog(date,pid);return true}};render()}
function timerScreenV(){const t=S.activeTimer||TIMER_DRAFT,p=findPart(t.part),a=p&&asg(t.date,p),total=partTimeSeconds(t.date,t.part),running=S.activeTimer&&S.activeTimer.running,planned=p?Math.max(1,(p.e-p.s)*60):0,elapsed=timerSeconds(),progress=Math.min(100,Math.round(elapsed/planned*100)),dim=Math.max(0,Math.min(85,S.timerDim))/100,bg=TIMER_BG_URL?`background-image:linear-gradient(rgba(7,12,24,${dim}),rgba(7,12,24,${dim})),url('${TIMER_BG_URL}');background-position:center;background-size:cover;background-repeat:no-repeat;`:'';return`<section class="time-screen${TIMER_BG_URL?' has-bg':''}" style="${bg}"><div class=timer-top><button class=timer-ghost data-a=timerBack>← بازگشت به پلنر</button></div><div class=timer-center><div class=timer-kicker>FOCUS SESSION</div><div class=timer-subject>${esc(a?cname(a.c):'مطالعه آزاد')}</div><div class=timer-part>${esc(p?.name||'پارت مطالعه')} · ${fj(t.date,1)}</div><div class=timer-digits id=timerDigits>${clockText(timerSeconds())}</div><div class=timer-state><i class=timer-dot style="${running?'':'background:#f3c76b;box-shadow:0 0 14px #f3c76b'}"></i>${running?'در حال ثبت زمان':'تایمر متوقف است'}</div><div class=timer-progress><div class=bar><i id=timerProgress style="width:${progress}%"></i></div><small id=timerProgressText>${p?'حدود '+fa(progress)+'٪ از زمان برنامه‌ریزی‌شده‌ی پارت':'مطالعه‌ی آزاد'}</small></div><div class=timer-glass><div class="muted sm" style="color:rgba(255,255,255,.68)">مجموع ثبت‌شده‌ی قبلی این پارت در این روز</div><b style="font-size:23px;font-variant-numeric:tabular-nums">${fsec(total)}</b></div><div class=timer-controls><button class=timer-main data-a=timerToggle>${running?'توقف موقت':t&&t.elapsedSec?'ادامه‌ی تایمر':'شروع مطالعه'}</button><button class=timer-finish data-a=timerFinish>پایان و ثبت زمان</button></div></div><div class=timer-bottom><span class=timer-ghost>تمرکز روی همین پارت</span><span class=timer-ghost>پس‌زمینه از تنظیمات پلنر</span></div></section>`}
function timerUpdate(){const sec=timerSeconds(),s=clockText(sec),e=$('#timerDigits');if(e)e.textContent=s;const b=$('#miniClock');if(b)b.textContent=s;const t=S.activeTimer||TIMER_DRAFT,p=t&&findPart(t.part),planned=p?Math.max(1,(p.e-p.s)*60):0,pct=planned?Math.min(100,Math.round(sec/planned*100)):0,bar=$('#timerProgress'),label=$('#timerProgressText');if(bar)bar.style.width=pct+'%';if(label)label.textContent=p?'حدود '+fa(pct)+'٪ از زمان برنامه‌ریزی‌شده‌ی پارت':'مطالعه‌ی آزاد'}
